            value = value.tolist()
        elif copy and isinstance(value, (list, tuple, np.ndarray)):
            value = value.copy()

        pa_array = pa.array(value, type=pa_type, mask=mask)

        if pa_type is not None and pa.types.is_duration(pa_type):
            from pandas.core.tools.timedeltas import to_timedelta

